79	
80	    ::selection {
81	      background: var(--accent);
82	      color: var(--bg);
83	    }
84	
85	    body {
86	      font-family: system-ui, -apple-system, sans-serif;
87	      max-width: 40rem;
88	      margin: 3rem auto;
89	      padding: 0 1rem;
90	      line-height: 1.6;
91	      color: var(--fg);
92	      background: var(--bg);
93	    }
94	
95	    @media (max-width: 30rem) {
96	      body {
97	        margin: 1.5rem auto;
